multimodal_workflow.py:
"""Deterministic v2 multimodal draft validation and controller state."""

from __future__ import annotations

import math
import uuid
from copy import deepcopy
from dataclasses import dataclass, field
from enum import Enum
from typing import Any, Mapping

from change_preview import model_digest
from image_preprocess import axis_mapping
from multimodal_contract import canonical_digest

V2_DRAFT_FORMAT = "space-frame-recognition-draft/v2"


class MultimodalPhase(str, Enum):
    IDLE = "idle"
    IMAGE_LOADED = "image_loaded"
    RECOGNIZING = "recognizing"
    REVIEW_REQUIRED = "review_required"
    READY_TO_COMMIT = "ready_to_commit"
    COMMITTING = "committing"
    COMMITTED = "committed"
    RECOGNITION_FAILED = "recognition_failed"


_DRAFT_HASH_FIELDS = (
    "format", "image_model", "model", "merge_plan", "source", "work_plane",
    "scale", "entities", "dimensions", "intersections", "issues", "revision",
)


def draft_digest(draft: Mapping[str, Any]) -> str:
    return canonical_digest({key: draft.get(key) for key in _DRAFT_HASH_FIELDS})


def _finite(value: Any) -> bool:
    return isinstance(value, (int, float)) and not isinstance(value, bool) \
        and math.isfinite(float(value))


def prepare_vision_entities(draft: dict) -> None:
    """把识别观察绑定到审核对象；缺失置信度保持未知，模型不能替用户确认。"""
    model = draft.get("image_model") or {}
    if not isinstance(model, dict) or not isinstance(model.get("nodes"), list):
        return
    nodes = {item["id"]: item for item in model["nodes"]
             if isinstance(item, dict) and isinstance(item.get("id"), int)
             and not isinstance(item["id"], bool) and "u" in item and "v" in item}
    expected = []
    observations = draft.get("entities") or []
    for ident, node in nodes.items():
        expected.append(("node", {"node": ident}, {"point": [node["u"], node["v"]]}))
    for member in model.get("members") or []:
        if (not isinstance(member, dict) or "id" not in member
                or not isinstance(member.get("i"), int) or not isinstance(member.get("j"), int)
                or member["i"] not in nodes or member["j"] not in nodes):
            continue
        a, b = nodes[member["i"]], nodes[member["j"]]
        expected.append(("member", {"member": member["id"]},
                         {"line": [[a["u"], a["v"]], [b["u"], b["v"]]]}))
    for index, support in enumerate(model.get("supports") or [], 1):
        if (not isinstance(support, dict) or not isinstance(support.get("node"), int)
                or support["node"] not in nodes):
            continue
        node = nodes[support["node"]]
        if not support.get("name"):
            observed_names = {
                target["name"] for entity in observations if isinstance(entity, dict)
                and entity.get("kind") == "support"
                and isinstance(entity.get("target"), dict)
                and isinstance(target := (entity.get("target") or {}).get("support"), dict)
                and target.get("node") == support["node"]
                and isinstance(target.get("name"), str) and target["name"].strip()
            }
            # 同一节点只有一个观察名称时沿用它，防止默认命名与真实响应冲突。
            support["name"] = next(iter(observed_names)) if len(observed_names) == 1 else f"S{support['node']}-{index}"
        expected.append(("support", {"support": {"node": support["node"], "name": support.get("name")}},
                         {"point": [node["u"], node["v"]]}))
    for case in model.get("load_cases") or []:
        if not isinstance(case, dict):
            continue
        for collection in ("nodal_loads", "member_loads", "member_spans", "settlements"):
            for index, load in enumerate(case.get(collection) or [], 1):
                if isinstance(load, dict):
                    if not load.get("name"):
                        load["name"] = f"{collection}-{index}"
                    geometry = {}
                    if isinstance(load.get("node"), int) and load["node"] in nodes:
                        node = nodes[load["node"]]
                        geometry = {"point": [node["u"], node["v"]]}
                    elif "member" in load:
                        geometry = next((g for k, t, g in expected if k == "member"
                                         and t["member"] == load["member"]), {})
                    expected.append(("load", {"load": {"case": case.get("name"),
                                     "collection": collection, "name": load.get("name")}}, geometry))
    entities = draft.get("entities")
    if not isinstance(entities, list):
        return
    unbound_loads = []
    for entity in entities:
        if not isinstance(entity, dict):
            raise ValueError("识别实体必须是对象，请重新输出实体列表。")
        confidence = entity.get("confidence")
        if confidence is not None and (not _finite(confidence) or not 0 <= confidence <= 1):
            raise ValueError("识别置信度必须为 0 到 1 的有限数或 null。")
        geometry = entity.get("image_geometry") or {}
        if not isinstance(geometry, dict):
            raise ValueError("识别实体 image_geometry 必须为对象。")
        for key, size in (("point", 2), ("bbox", 4), ("line", 2)):
            if key not in geometry:
                continue
            values = geometry[key]
            if not isinstance(values, (list, tuple)) or len(values) != size:
                raise ValueError(f"识别位置 {key} 的分量数量无效。")
            if key == "line":
                if any(not isinstance(p, (list, tuple)) or len(p) != 2 for p in values):
                    raise ValueError("识别线段必须包含两个二维端点。")
                values = [component for point in values for component in point]
            if any(not _finite(value) or not 0 <= value <= 1 for value in values):
                raise ValueError("识别位置必须为 0 到 1 的有限归一化坐标。")
        entity.update(source="vision", verified=False, recognition_confidence=confidence)
        kind = entity.get("kind")
        target = entity.get("target") or {}
        if not isinstance(target, dict):
            raise ValueError("识别实体 target 必须为对象。")
        if kind == "dimension":
            dimension = next((item for item in draft.get("dimensions") or []
                              if isinstance(item, dict) and item.get("id") == target.get("dimension")), None)
            if dimension is None:
                raise ValueError("尺寸观察必须引用 dimensions 中存在的标注。")
            # 尺寸证据属于尺寸审核，不作为结构对象；保留观察位置与未知置信度。
            dimension.update(recognition_confidence=confidence, source="vision", verified=False)
            if geometry:
                dimension["image_geometry"] = deepcopy(geometry)
            continue
        if kind in {"node", "member"}:
            ident = target.get(kind, entity.get(kind, entity.get("id")))
            target = {kind: ident}
        elif kind == "support" and "support" not in target:
            ident = target.get("node", entity.get("node"))
            candidate = next((t for k, t, _ in expected if k == kind
                              and t["support"]["node"] == ident), None)
            target = candidate or target
        elif kind == "load" and "load" not in target:
            candidate = next((t for k, t, _ in expected if k == kind
                              and t["load"]["case"] == target.get("case", entity.get("case"))
                              and t["load"]["name"] == target.get("name", entity.get("name"))), None)
            target = candidate or target
        entity["target"] = deepcopy(target)
        if not any(kind == k and target == t for k, t, _ in expected):
            if kind == "load":
                # 无求解条目的符号观察单独隔离，不能补零，也不能令整份几何丢失。
                unbound_loads.append(entity)
                continue
            raise ValueError("识别实体必须引用 image_model 中存在的审核对象，请检查 target。")
    if unbound_loads:
        issues = draft.setdefault("issues", [])
        problem = next((issue for issue in issues if issue.get("category") == "load_incomplete"
                        and not issue.get("entity_refs")), None)
        symbols_only = problem is None
        if problem is None:
            ident = f"unbound-load-{len(issues) + 1}"
            while any(issue.get("id") == ident for issue in issues):
                ident += "-new"
            problem = {"id": ident, "category": "load_incomplete", "entity_refs": [],
                "message": "荷载符号观察没有对应的求解条目，可能缺少数值或属于反力。请核对作用位置、物理含义及数值；明确无需施加时选择忽略符号，原记录仍保留。"}
            issues.append(problem)
        problem.update(severity="blocking", status="open", resolution=None, resolved_by=None,
                       observations=deepcopy(unbound_loads), unbound_symbols_only=symbols_only)
    entities[:] = [entity for entity in entities if entity.get("kind") != "dimension"
                   and not any(entity is unknown for unknown in unbound_loads)]
    for index, (kind, target, geometry) in enumerate(expected, 1):
        match = next((entity for entity in entities if entity.get("kind") == kind
                      and entity.get("target") == target), None)
        if match is None:
            ident = f"review-{kind}-{index}"
            while any(entity.get("id") == ident for entity in entities):
                ident += "-missing"
            entities.append({"id": ident, "kind": kind, "target": deepcopy(target),
                             "image_geometry": geometry, "confidence": None,
                             "recognition_confidence": None, "verified": False, "source": "derived"})
        elif not match.get("image_geometry"):
            match["image_geometry"] = geometry


def _work_plane_errors(work_plane: Any) -> list[str]:
    """按 v2 契约逐字检查 work_plane。

    物化时 image_to_model 只认 work_plane["plane"]，自己重算轴映射。草稿里
    声明的 axis_mapping 一个字都不读——所以它必须在这里被钉死，否则草稿可以
    声明一套映射、几何按另一套生成，而用户在确认界面上看到的是前者。
    """
    if not isinstance(work_plane, dict)             or work_plane.get("status") not in ("proposed", "confirmed")             or work_plane.get("plane") not in ("XY", "XZ", "YZ"):
        return ["work_plane 无效"]
    errors: list[str] = []
    if not _finite(work_plane.get("offset")):
        errors.append("work_plane.offset 必须是有限数")
    expected = axis_mapping(work_plane["plane"])
    mapping = work_plane.get("axis_mapping")
    if not isinstance(mapping, dict):
        errors.append("work_plane.axis_mapping 必须是对象")
        return errors
    if set(mapping) != set(expected):
        errors.append(f"work_plane.axis_mapping 的字段必须恰好是 "
                      f"{sorted(expected)}，实际 {sorted(mapping)}")
        return errors
    for key in ("first_axis", "second_axis", "offset_axis"):
        if mapping[key] != expected[key]:
            errors.append(
                f"work_plane.axis_mapping.{key} 与 plane="
                f"{work_plane['plane']} 矛盾：契约要求 {expected[key]!r}，"
                f"草稿写的是 {mapping[key]!r}。物化只认 plane，"
                "这里放行就会「确认一套、生成另一套」。")
    for key in ("image_right_sign", "image_up_sign"):
        if not isinstance(mapping[key], int) or isinstance(mapping[key], bool)                 or mapping[key] != 1:
            errors.append(
                f"work_plane.axis_mapping.{key} 固定为整数 1，草稿写的是 "
                f"{mapping[key]!r}；image_to_model 不读这个字段，"
                "写别的值不会让图像方向翻转。")
    return errors


def validate_v2_draft(draft: Any) -> list[str]:
    errors: list[str] = []
    if not isinstance(draft, dict):
        return ["v2 草稿必须是对象"]
    required = {*_DRAFT_HASH_FIELDS, "confirmation"}
    missing = sorted(required - set(draft))
    if missing:
        errors.append(f"v2 草稿缺少字段: {missing}")
        return errors
    if draft.get("format") != V2_DRAFT_FORMAT:
        errors.append(f"format 必须是 {V2_DRAFT_FORMAT}")
    if not isinstance(draft.get("revision"), int) or draft["revision"] < 0:
        errors.append("revision 必须是非负整数")

    image_model = draft.get("image_model")
    if not isinstance(image_model, dict):
        errors.append("image_model 必须是对象")
        return errors
    nodes = image_model.get("nodes")
    members = image_model.get("members")
    if not isinstance(nodes, list) or not isinstance(members, list):
        errors.append("image_model.nodes/members 必须是数组")
        return errors
    node_ids: set[int] = set()
    for node in nodes:
        if not isinstance(node, dict) or not isinstance(node.get("id"), int):
            errors.append("image_model 节点必须包含整数 id")
            continue
        node_id = node["id"]
        if node_id <= 0 or node_id in node_ids:
            errors.append(f"image_model 节点 id 无效或重复: {node_id}")
        node_ids.add(node_id)
        if not (_finite(node.get("u")) and _finite(node.get("v"))
                and 0.0 <= float(node["u"]) <= 1.0
                and 0.0 <= float(node["v"]) <= 1.0):
            errors.append(f"image_model 节点 {node_id} 的 u/v 无效")
    member_ids: set[int] = set()
    edges: dict[tuple[int, int], int] = {}
    for member in members:
        if not isinstance(member, dict) or not isinstance(member.get("id"), int):
            errors.append("image_model 杆件必须包含整数 id")
            continue
        member_id = member["id"]
        i, j = member.get("i"), member.get("j")
        if member_id <= 0 or member_id in member_ids:
            errors.append(f"image_model 杆件 id 无效或重复: {member_id}")
        member_ids.add(member_id)
        if i not in node_ids or j not in node_ids:
            errors.append(f"image_model 杆件 {member_id} 引用悬空")
            continue
        edge = tuple(sorted((int(i), int(j))))
        if i == j:
            errors.append(f"image_model 杆件 {member_id} 自连接：两端均为节点 {i}。请核对原图端点。")
        elif edge in edges:
            errors.append(f"image_model 杆件 {member_id} 与杆件 {edges[edge]} 重复："
                          f"两者连接节点 {edge[0]} 和 {edge[1]}，反向仍为同一杆件。请核对原图连接，修正端点或移除重复记录。")
        else:
            edges[edge] = member_id

    errors.extend(_work_plane_errors(draft.get("work_plane")))
    scale = draft.get("scale")
    if not isinstance(scale, dict) or scale.get("status") not in (
            "unknown", "confirmed", "conflict"):
        errors.append("scale 无效")
    elif scale["status"] == "confirmed":
        if not _finite(scale.get("length_per_pixel")) \
                or float(scale["length_per_pixel"]) <= 0:
            errors.append("confirmed scale 必须包含有限正比例")
    elif scale.get("length_per_pixel") is not None:
        errors.append("未确认 scale 的 length_per_pixel 必须为 null")

    for key in ("entities", "dimensions", "intersections", "issues"):
        if not isinstance(draft.get(key), list):
            errors.append(f"{key} 必须是数组")
    model = draft.get("model")
    if model is not None and not isinstance(model, dict):
        errors.append("model 必须是对象或 null")
    merge_plan = draft.get("merge_plan")
    if merge_plan is not None and not isinstance(merge_plan, dict):
        errors.append("merge_plan 必须是对象或 null")
    return errors


def _proxy_points(model: Mapping[str, Any]) -> dict[int, tuple[float, float]]:
    nodes = model.get("nodes") or []
    ranges = []
    for order, axis in enumerate(("x", "y", "z")):
        values = [float(node.get(axis, 0.0)) for node in nodes]
        spread = max(values, default=0.0) - min(values, default=0.0)
        ranges.append((-spread, order, axis, values))
    ranges.sort()
    first, second = ranges[0], ranges[1]

    def normalized(values: list[float], value: float) -> float:
        low, high = min(values, default=0.0), max(values, default=0.0)
        return 0.5 if high == low else (value - low) / (high - low)

    result = {}
    for index, node in enumerate(nodes):
        result[int(node["id"])] = (
            normalized(first[3], first[3][index]),
            1.0 - normalized(second[3], second[3][index]),
        )
    return result


def migrate_v1_payload(payload: Mapping[str, Any], *, image_hash: str = "",
                       source_path: str = "") -> dict[str, Any]:
    """Deterministically preserve a v1 graph without trusting its scale."""
    model = deepcopy(payload.get("model", payload))
    if not isinstance(model, dict) or not model.get("nodes") or not model.get("members"):
        raise ValueError("v1 草稿缺少 nodes/members")
    points = _proxy_points(model)
    old_entities = payload.get("entities") or []
    point_entities = {
        int(item["id"]): item["image_geometry"]["point"]
        for item in old_entities
        if item.get("kind") == "node" and isinstance(item.get("image_geometry"), dict)
        and isinstance(item["image_geometry"].get("point"), list)
        and len(item["image_geometry"]["point"]) == 2
    }
    use_evidence = len(point_entities) == len(model["nodes"])
    if use_evidence:
        points = {node_id: (float(point[0]), float(point[1]))
                  for node_id, point in point_entities.items()}
    image_nodes = [{"id": int(node["id"]), "u": points[int(node["id"])][0],
                    "v": points[int(node["id"])][1]}
                   for node in model["nodes"]]
    image_members = [{"id": int(item["id"]), "i": int(item["i"]),
                      "j": int(item["j"]),
                      "material": item.get("material") or None,
                      "section": item.get("section") or None}
                     for item in model["members"]]
    old_by_kind_id = {(str(item.get("kind")), str(item.get("id"))): item
                      for item in old_entities if isinstance(item, dict)}

    def migrated_entity(kind: str, legacy_id: Any, geometry: dict[str, Any],
                        target: dict[str, Any], entity_payload: dict[str, Any]) -> dict[str, Any]:
        previous = old_by_kind_id.get((kind, str(legacy_id)), {})
        previous_confidence = previous.get("confidence")
        recognition_confidence = (float(previous_confidence)
                                  if _finite(previous_confidence)
                                  and 0.0 <= float(previous_confidence) <= 1.0
                                  else None)
        return {"kind": kind, "id": f"{kind}-{legacy_id}",
                "confidence": None, "recognition_confidence": recognition_confidence,
                "verified": False, "source": "migration",
                "image_geometry": deepcopy(previous.get("image_geometry") or geometry),
                "target": target, "payload": deepcopy(entity_payload)}

    entities = []
    for node in image_nodes:
        entities.append(migrated_entity(
            "node", node["id"], {"point": [node["u"], node["v"]]},
            {"node": node["id"]}, {}))
    for member in image_members:
        a = points[member["i"]]
        b = points[member["j"]]
        entities.append(migrated_entity(
            "member", member["id"], {"line": [list(a), list(b)]},
            {"member": member["id"]}, {}))
    supports = deepcopy(model.get("supports") or [])
    for index, support in enumerate(supports):
        support.setdefault("name", f"S{support['node']}-{index + 1}")
        node_id = int(support["node"])
        point = points[node_id]
        entities.append(migrated_entity(
            "support", support["name"], {"point": list(point)},
            {"support": {"node": node_id, "name": support["name"]}}, support))

    top_level_loads = {key: deepcopy(model.get(key) or []) for key in (
        "nodal_loads", "member_loads", "member_spans", "settlements")}
    load_cases = deepcopy(model.get("load_cases") or [])

    def add_load_entities(case_name: str, container: dict[str, Any]) -> None:
        for collection in ("nodal_loads", "member_loads", "member_spans", "settlements"):
            for index, load in enumerate(container.get(collection) or []):
                load.setdefault("name", f"{collection}-{index + 1}")
                if "node" in load:
                    geometry = {"point": list(points[int(load["node"])])}
                else:
                    member = next(item for item in image_members
                                  if item["id"] == int(load["member"]))
                    geometry = {"line": [list(points[member["i"]]),
                                         list(points[member["j"]])]}
                legacy_id = f"{case_name}:{load['name']}"
                entities.append(migrated_entity(
                    "load", legacy_id, geometry,
                    {"load": {"case": case_name, "collection": collection,
                              "name": load["name"]}}, load))

    add_load_entities("__top__", top_level_loads)
    for case in load_cases:
        add_load_entities(str(case.get("name", "default")), case)
    refs = [f"node:{item['id']}" for item in image_nodes]
    return {
        "format": V2_DRAFT_FORMAT,
        "image_model": {
            "nodes": image_nodes, "members": image_members,
            "supports": supports,
            **top_level_loads,
            "load_cases": load_cases,
        },
        "model": None,
        "merge_plan": None,
        "source": {"original_path": source_path, "image_hash": image_hash,
                   "preprocessing": {"perspective_status": "unconfirmed"}},
        "work_plane": {"status": "proposed", "plane": "XZ", "offset": 0.0,
                       "axis_mapping": {"first_axis": "X", "second_axis": "Z",
                                        "offset_axis": "Y", "image_right_sign": 1,
                                        "image_up_sign": 1}},
        "scale": {"status": "unknown", "length_per_pixel": None,
                  "unit": "m/px", "anchor_node": image_nodes[0]["id"],
                  "anchor_coordinates_xyz": [0.0, 0.0, 0.0],
                  "evidence_ids": []},
        "entities": entities,
        "dimensions": [], "intersections": [],
        "issues": [{"id": "migration-review", "category": "low_confidence",
                    "severity": "blocking", "entity_refs": refs,
                    "message": "旧版图片坐标需要人工确认",
                    "status": "open", "resolution": None, "resolved_by": None}],
        "revision": 0, "confirmation": None,
    }


@dataclass
class MultimodalControllerState:
    workflow_instance_id: str = ""
    image_hash: str = ""
    draft: dict[str, Any] | None = None
    job_status: str = "idle"
    job_id: str | None = None
    commit_status: str = "idle"
    commit_preview: dict[str, Any] | None = None
    commit_receipt: dict[str, Any] | None = None
    last_error: str | None = None
    commit_error: str | None = None
    _previous_draft: dict[str, Any] | None = field(default=None, repr=False)

    def load_image(self, image_hash: str) -> None:
        if not image_hash:
            raise ValueError("image_hash 不能为空")
        self.workflow_instance_id = str(uuid.uuid4())
        self.image_hash = image_hash
        self.draft = None
        self.job_status, self.job_id = "idle", None
        self.commit_status = "idle"
        self.commit_preview = self.commit_receipt = None
        self.last_error = self.commit_error = None
        self._previous_draft = None

    def start_recognition(self, job_id: str | None = None) -> str:
        if not self.image_hash or self.job_status == "running":
            raise RuntimeError("当前不能开始识别")
        self._previous_draft = deepcopy(self.draft)
        if self._previous_draft is not None:
            self._previous_draft["confirmation"] = None
            self._previous_draft["merge_plan"] = None
            self.draft = deepcopy(self._previous_draft)
        self.job_status = "running"
        self.job_id = job_id or str(uuid.uuid4())
        self.last_error = None
        self.commit_preview = self.commit_receipt = None
        return self.job_id

    def cancel_recognition(self, job_id: str) -> bool:
        if self.job_status != "running" or job_id != self.job_id:
            return False
        self.job_status, self.job_id = "idle", None
        self.draft = self._previous_draft
        self._previous_draft = None
        return True

    def complete_recognition(self, job_id: str, draft: dict[str, Any]) -> bool:
        if self.job_status != "running" or job_id != self.job_id:
            return False
        errors = validate_v2_draft(draft)
        if (draft.get("source") or {}).get("image_hash") != self.image_hash:
            errors.append("识别草稿 image_hash 与当前图片不一致")
        if errors:
            self.fail_recognition(job_id, "；".join(errors))
            return False
        self.draft = deepcopy(draft)
        self.job_status, self.job_id = "idle", None
        self.last_error = None
        self._previous_draft = None
        return True

    def fail_recognition(self, job_id: str, error: str) -> bool:
        if self.job_status != "running" or job_id != self.job_id:
            return False
        self.job_status, self.job_id = "idle", None
        self.draft = self._previous_draft
        self._previous_draft = None
        self.last_error = str(error)
        return True

    def edit_draft(self, draft: dict[str, Any]) -> None:
        if self.draft is None:
            raise RuntimeError("没有可编辑草稿")
        edited = deepcopy(draft)
        edited["revision"] = int(self.draft.get("revision", 0)) + 1
        edited["confirmation"] = None
        edited["merge_plan"] = None
        errors = validate_v2_draft(edited)
        if errors:
            raise ValueError("；".join(errors))
        self.draft = edited
        self.commit_preview = self.commit_receipt = None
        self.commit_error = None

    def set_commit_preview(self, preview: Mapping[str, Any]) -> None:
        if self.draft is None:
            raise RuntimeError("没有草稿")
        if preview.get("draft_hash") != draft_digest(self.draft):
            raise ValueError("preview draft_hash 已陈旧")
        if preview.get("merge_plan_hash") != canonical_digest(self.draft.get("merge_plan")):
            raise ValueError("preview merge_plan_hash 已陈旧")
        self.commit_preview = deepcopy(dict(preview))

    def install_commit_preview(self, prepared_draft: Mapping[str, Any],
                               preview: Mapping[str, Any]) -> None:
        """Install a plan produced from the current draft without faking an edit."""
        if self.draft is None:
            raise RuntimeError("没有草稿")
        current = deepcopy(self.draft)
        prepared = deepcopy(dict(prepared_draft))
        # model 是已确认 image_model/work-plane/scale 的确定性物化结果，
        # 与 merge_plan 一起安装，不属于一次新的人工编辑。
        current["model"] = deepcopy(prepared.get("model"))
        current["merge_plan"] = prepared["merge_plan"] = None
        current["confirmation"] = prepared["confirmation"] = None
        if draft_digest(current) != draft_digest(prepared):
            raise ValueError("合并计划不是由当前草稿生成")
        installed = deepcopy(dict(prepared_draft))
        errors = validate_v2_draft(installed)
        if errors:
            raise ValueError("；".join(errors))
        self.draft = installed
        self.set_commit_preview(preview)

    def phase(self, session_model: Mapping[str, Any]) -> MultimodalPhase:
        if self.commit_status == "running":
            return MultimodalPhase.COMMITTING
        if self.job_status == "running":
            return MultimodalPhase.RECOGNIZING
        if self.last_error and self.draft is None:
            return MultimodalPhase.RECOGNITION_FAILED
        if self._receipt_matches(session_model):
            return MultimodalPhase.COMMITTED
        if self.image_hash and self.draft is None:
            return MultimodalPhase.IMAGE_LOADED
        if self.draft is not None:
            return (MultimodalPhase.READY_TO_COMMIT
                    if self._ready(session_model) else MultimodalPhase.REVIEW_REQUIRED)
        return MultimodalPhase.IDLE

    def can_commit(self, session_model: Mapping[str, Any]) -> bool:
        return (self.job_status == "idle" and self.commit_status == "idle"
                and self.phase(session_model) == MultimodalPhase.READY_TO_COMMIT)

    def start_commit(self, session_model: Mapping[str, Any], *, confirmed_at: str) -> bool:
        if not self.can_commit(session_model) or self.draft is None \
                or self.commit_preview is None:
            return False
        self.draft["confirmation"] = {
            "revision": self.draft["revision"],
            "draft_hash": draft_digest(self.draft),
            "baseline_model_hash": model_digest(dict(session_model)),
            "preview_id": self.commit_preview["preview_id"],
            "diff_hash": self.commit_preview["diff_hash"],
            "confirmed_at": confirmed_at,
        }
        self.commit_status = "running"
        self.commit_error = None
        return True

    def finish_commit(self, *, success: bool, model_hash: str = "",
                      committed_at: str = "", history_step_id: str = "") -> None:
        if self.commit_status != "running" or self.draft is None:
            raise RuntimeError("没有进行中的提交")
        self.commit_status = "idle"
        if not success:
            self.commit_error = "提交失败"
            return
        self.commit_receipt = {
            "workflow_instance_id": self.workflow_instance_id,
            "image_hash": self.image_hash,
            "draft_hash": draft_digest(self.draft),
            "revision": self.draft["revision"],
            "model_hash": model_hash,
            "committed_at": committed_at,
            "history_step_id": history_step_id,
        }

    def _ready(self, session_model: Mapping[str, Any]) -> bool:
        if self.draft is None or validate_v2_draft(self.draft):
            return False
        draft = self.draft
        blocking = any(issue.get("severity") == "blocking"
                       and issue.get("status") == "open"
                       for issue in draft["issues"])
        perspective = ((draft.get("source") or {}).get("preprocessing") or {}).get(
            "perspective_status")
        preview = self.commit_preview
        return bool(
            draft["work_plane"].get("status") == "confirmed"
            and draft["scale"].get("status") == "confirmed"
            and isinstance(draft.get("model"), dict)
            and isinstance(draft.get("merge_plan"), dict)
            and perspective == "accepted" and not blocking and preview
            and preview.get("draft_hash") == draft_digest(draft)
            and preview.get("merge_plan_hash") == canonical_digest(draft["merge_plan"])
            and preview.get("baseline_model_hash") == model_digest(dict(session_model))
        )

    def _receipt_matches(self, session_model: Mapping[str, Any]) -> bool:
        if self.draft is None or not self.commit_receipt:
            return False
        receipt = self.commit_receipt
        return bool(
            receipt.get("workflow_instance_id") == self.workflow_instance_id
            and receipt.get("image_hash") == self.image_hash
            and receipt.get("draft_hash") == draft_digest(self.draft)
            and receipt.get("revision") == self.draft.get("revision")
            and receipt.get("model_hash") == model_digest(dict(session_model))
        )

dimension_constraints.py:
"""Deterministic dimension evidence and image-scale resolution for v2 drafts."""

from __future__ import annotations

import math
from copy import deepcopy
from statistics import median
from typing import Any, Mapping

from multimodal_contract import SCALE_CONFLICT_RATIO
from units import MM, SI, system


LINEAR_KINDS = {
    "member_length", "node_distance", "horizontal_distance", "vertical_distance",
}
_UNIT_TO_M = {
    "m": system(SI).length_to_m,
    "mm": system(MM).length_to_m,
    "cm": 0.01,
}


def _finite(value: Any) -> bool:
    return isinstance(value, (int, float)) and not isinstance(value, bool) \
        and math.isfinite(float(value))


def length_to_m(value: Any, unit: Any) -> float | None:
    """Convert a positive dimension to metres; missing/unknown units are unusable."""
    if not _finite(value) or float(value) <= 0 or not isinstance(unit, str):
        return None
    factor = _UNIT_TO_M.get(unit.strip().lower())
    return None if factor is None else float(value) * factor


def default_anchor_node(image_model: Mapping[str, Any]) -> int:
    """Choose left-most, then lowest, then smallest-id image node."""
    nodes = image_model.get("nodes") or []
    if not nodes:
        raise ValueError("image_model 没有节点")
    try:
        return int(min(nodes, key=lambda item: (
            float(item["u"]), -float(item["v"]), int(item["id"])))["id"])
    except (KeyError, TypeError, ValueError) as exc:
        raise ValueError("image_model 节点坐标无效") from exc


def _node_points(image_model: Mapping[str, Any]) -> dict[int, tuple[float, float]]:
    result: dict[int, tuple[float, float]] = {}
    for node in image_model.get("nodes") or []:
        node_id = int(node["id"])
        point = float(node["u"]), float(node["v"])
        if node_id in result or not all(_finite(value) and 0 <= value <= 1
                                        for value in point):
            raise ValueError("image_model 节点 ID 或坐标无效")
        result[node_id] = point
    return result


def _dimension_nodes(dimension: Mapping[str, Any],
                     image_model: Mapping[str, Any]) -> tuple[int, int]:
    target = dimension.get("target") or {}
    if dimension.get("kind") == "member_length":
        member_id = target.get("member")
        members = [item for item in image_model.get("members") or []
                   if item.get("id") == member_id]
        if len(members) != 1:
            raise ValueError(f"尺寸 {dimension.get('id')} 引用未知杆件 {member_id}")
        return int(members[0]["i"]), int(members[0]["j"])
    nodes = target.get("nodes")
    if not isinstance(nodes, list) or len(nodes) != 2:
        raise ValueError(f"尺寸 {dimension.get('id')} 必须引用两个节点")
    return int(nodes[0]), int(nodes[1])


def dimension_pixel_length(dimension: Mapping[str, Any],
                           image_model: Mapping[str, Any],
                           width_px: int, height_px: int) -> float:
    if width_px <= 1 or height_px <= 1:
        raise ValueError("派生图宽高必须大于 1")
    points = _node_points(image_model)
    i, j = _dimension_nodes(dimension, image_model)
    try:
        a, b = points[i], points[j]
    except KeyError as exc:
        raise ValueError(f"尺寸 {dimension.get('id')} 引用悬空节点") from exc
    dx = abs((b[0] - a[0]) * (width_px - 1))
    dy = abs((b[1] - a[1]) * (height_px - 1))
    kind = dimension.get("kind")
    if kind == "horizontal_distance":
        pixels = dx
    elif kind == "vertical_distance":
        pixels = dy
    else:
        pixels = math.hypot(dx, dy)
    if pixels <= 0 or not math.isfinite(pixels):
        raise ValueError(f"尺寸 {dimension.get('id')} 的目标像素长度为零")
    return pixels


def solve_scale(image_model: Mapping[str, Any], dimensions: list[dict[str, Any]],
                width_px: int, height_px: int, *,
                trusted_dimension_id: str | None = None) -> tuple[dict[str, Any], list[dict[str, Any]]]:
    """Return a v2 scale block and copied dimensions with conflict decisions."""
    updated = deepcopy(dimensions)
    candidates: list[tuple[str, float, dict[str, Any]]] = []
    for item in updated:
        if item.get("kind") not in LINEAR_KINDS or item.get("status") != "confirmed":
            continue
        metres = length_to_m(item.get("value"), item.get("unit"))
        if metres is None:
            continue
        evidence_id = f"dimension:{item.get('id')}"
        pixels = dimension_pixel_length(item, image_model, width_px, height_px)
        candidates.append((evidence_id, metres / pixels, item))
    candidates.sort(key=lambda entry: entry[0])

    if trusted_dimension_id is not None:
        trusted_ref = (trusted_dimension_id if str(trusted_dimension_id).startswith("dimension:")
                       else f"dimension:{trusted_dimension_id}")
        chosen = [entry for entry in candidates if entry[0] == trusted_ref]
        if len(chosen) != 1:
            raise ValueError("指定的可信尺寸不是可用的 confirmed 线性尺寸")
        for evidence_id, _, item in candidates:
            if evidence_id != trusted_ref:
                item["status"] = "rejected_conflict"
        return ({"status": "confirmed", "length_per_pixel": chosen[0][1],
                 "unit": "m/px", "anchor_node": default_anchor_node(image_model),
                 "anchor_coordinates_xyz": [0.0, 0.0, 0.0],
                 "evidence_ids": [trusted_ref]}, updated)

    if not candidates:
        return ({"status": "unknown", "length_per_pixel": None,
                 "unit": "m/px", "anchor_node": default_anchor_node(image_model),
                 "anchor_coordinates_xyz": [0.0, 0.0, 0.0],
                 "evidence_ids": []}, updated)
    middle = float(median(entry[1] for entry in candidates))
    ratios = [abs(value - middle) / middle for _, value, _ in candidates]
    conflict = any(ratio > SCALE_CONFLICT_RATIO
                   and not math.isclose(ratio, SCALE_CONFLICT_RATIO,
                                        rel_tol=0.0, abs_tol=1e-12)
                   for ratio in ratios)
    return ({"status": "conflict" if conflict else "confirmed",
             "length_per_pixel": None if conflict else middle,
             "unit": "m/px", "anchor_node": default_anchor_node(image_model),
             "anchor_coordinates_xyz": [0.0, 0.0, 0.0],
             "evidence_ids": [] if conflict else [entry[0] for entry in candidates]}, updated)


def apply_scale_to_draft(draft: Mapping[str, Any], *,
                         trusted_dimension_id: str | None = None) -> dict[str, Any]:
    """Purely resolve scale from a v2 draft; the input draft is never modified."""
    updated = deepcopy(dict(draft))
    source = updated.get("source") or {}
    scale, dimensions = solve_scale(
        updated.get("image_model") or {}, updated.get("dimensions") or [],
        int(source.get("width_px", 0)), int(source.get("height_px", 0)),
        trusted_dimension_id=trusted_dimension_id)
    old = updated.get("scale") or {}
    for key in ("anchor_node", "anchor_coordinates_xyz"):
        if old.get(key) is not None:
            scale[key] = deepcopy(old[key])
    updated["scale"] = scale
    updated["dimensions"] = dimensions
    _sync_scale_issues(updated)
    return updated


def add_member_length_dimension(draft: Mapping[str, Any], member_id: int,
                                value: float, unit: str = "m") -> dict[str, Any]:
    """Add one traceable user-confirmed member-length dimension to a draft copy."""
    updated = deepcopy(dict(draft))
    image_model = updated.get("image_model") or {}
    members = [item for item in image_model.get("members") or []
               if item.get("id") == member_id]
    if len(members) != 1 or length_to_m(value, unit) is None:
        raise ValueError("杆件或实际长度无效")
    points = _node_points(image_model)
    member = members[0]
    try:
        start, end = points[int(member["i"])], points[int(member["j"])]
    except KeyError as exc:
        raise ValueError("杆件引用悬空节点") from exc
    dimensions = updated.setdefault("dimensions", [])
    used = {str(item.get("id")) for item in dimensions}
    sequence = 1
    while f"user-member-{member_id}-{sequence}" in used:
        sequence += 1
    identifier = f"user-member-{member_id}-{sequence}"
    dimensions.append({
        "id": identifier, "kind": "member_length",
        "text": f"{float(value):g} {unit}", "value": float(value), "unit": unit,
        "image_geometry": {"line": [list(start), list(end)]},
        "target": {"member": member_id}, "confidence": None,
        "recognition_confidence": None, "verified": True, "source": "user",
        "status": "confirmed",
    })
    return updated


def _sync_scale_issues(draft: dict[str, Any]) -> None:
    status = draft["scale"]["status"]
    active = {"unknown": "scale_unknown", "conflict": "scale_conflict"}.get(status)
    issues = draft.setdefault("issues", [])
    by_category = {item.get("category"): item for item in issues
                   if item.get("category") in {"scale_unknown", "scale_conflict"}}
    for category in ("scale_unknown", "scale_conflict"):
        issue = by_category.get(category)
        if category == active:
            if issue is None:
                issue = {"id": category, "category": category,
                         "severity": "blocking", "entity_refs": [],
                         "message": ("缺少可用的线性尺寸证据" if category == "scale_unknown"
                                     else "尺寸证据相互冲突"),
                         "status": "open", "resolution": None,
                         "resolved_by": None}
                issues.append(issue)
            else:
                issue.update(status="open", resolution=None, resolved_by=None,
                             severity="blocking")
        elif issue is not None and issue.get("status") == "open":
            issue.update(status="resolved", resolution="尺度状态已重新计算",
                         resolved_by="system")

sketch_topology.py:
"""Deterministic 2-D intersection detection and topology decisions for v2 drafts."""

from __future__ import annotations

import math
from copy import deepcopy
from typing import Any, Mapping

from image_preprocess import image_to_model
from multimodal_contract import (ENDPOINT_MATCH_ABS_PX,
                                 ENDPOINT_MATCH_DIAGONAL_RATIO,
                                 point_match_threshold)


def _cross(a: tuple[float, float], b: tuple[float, float]) -> float:
    return a[0] * b[1] - a[1] * b[0]


def _point(node: Mapping[str, Any]) -> tuple[float, float]:
    point = float(node["u"]), float(node["v"])
    if not all(math.isfinite(value) and 0 <= value <= 1 for value in point):
        raise ValueError("节点图片坐标无效")
    return point


def _geometry(image_model: Mapping[str, Any]):
    nodes = {int(item["id"]): _point(item) for item in image_model.get("nodes") or []}
    members = {int(item["id"]): item for item in image_model.get("members") or []}
    if len(nodes) != len(image_model.get("nodes") or []) \
            or len(members) != len(image_model.get("members") or []):
        raise ValueError("节点或杆件 ID 重复")
    for member in members.values():
        if int(member["i"]) not in nodes or int(member["j"]) not in nodes:
            raise ValueError(f"杆件 {member['id']} 引用悬空节点")
    return nodes, members


def _intersection(a, b, c, d):
    r, s = (b[0] - a[0], b[1] - a[1]), (d[0] - c[0], d[1] - c[1])
    denominator = _cross(r, s)
    q = c[0] - a[0], c[1] - a[1]
    if abs(denominator) <= 1e-12:
        return None
    ta, tb = _cross(q, s) / denominator, _cross(q, r) / denominator
    if -1e-12 <= ta <= 1 + 1e-12 and -1e-12 <= tb <= 1 + 1e-12:
        return ta, tb, (a[0] + ta * r[0], a[1] + ta * r[1])
    return None


def _collinear_overlap(a, b, c, d) -> bool:
    axis = 0 if abs(b[0] - a[0]) >= abs(b[1] - a[1]) else 1
    overlap = min(max(a[axis], b[axis]), max(c[axis], d[axis])) \
        - max(min(a[axis], b[axis]), min(c[axis], d[axis]))
    return overlap > 1e-12


def _endpoint_tolerance(width: int, height: int) -> float:
    return max(ENDPOINT_MATCH_ABS_PX,
               math.hypot(width - 1, height - 1) * ENDPOINT_MATCH_DIAGONAL_RATIO)


def _snap_parameter(value: float, length_px: float, tolerance_px: float) -> float:
    if value * length_px <= tolerance_px:
        return 0.0
    if (1.0 - value) * length_px <= tolerance_px:
        return 1.0
    return float(value)


def _issue(identifier: str, category: str, refs: list[str], message: str) -> dict[str, Any]:
    return {"id": identifier, "category": category, "severity": "blocking",
            "entity_refs": sorted(set(refs)), "message": message, "status": "open",
            "resolution": None, "resolved_by": None}


def detect_topology(draft: Mapping[str, Any]) -> dict[str, Any]:
    """Recompute pairwise 2-D intersections and stable blocking issues."""
    updated = deepcopy(dict(draft))
    image_model = updated.get("image_model") or {}
    nodes, members = _geometry(image_model)
    source = updated.get("source") or {}
    width, height = int(source.get("width_px", 0)), int(source.get("height_px", 0))
    if width <= 1 or height <= 1:
        raise ValueError("派生图宽高必须大于 1")
    tolerance = _endpoint_tolerance(width, height)
    old = {tuple(item.get("members") or []): item
           for item in updated.get("intersections") or []}
    intersections, generated_issues = [], []
    member_items = sorted(members.items())
    for index, (aid, first) in enumerate(member_items):
        ai, aj = int(first["i"]), int(first["j"])
        a, b = nodes[ai], nodes[aj]
        for bid, second in member_items[index + 1:]:
            bi, bj = int(second["i"]), int(second["j"])
            c, d = nodes[bi], nodes[bj]
            pair = [aid, bid]
            shared_endpoints = {ai, aj} & {bi, bj}
            if {ai, aj} == {bi, bj}:
                generated_issues.append(_issue(
                    f"duplicate-member-{aid}-{bid}", "topology",
                    [f"member:{aid}", f"member:{bid}"], "重复杆件"))
                continue
            hit = _intersection(a, b, c, d)
            if hit is None:
                # 共线重叠仍需处理，不能以共享端点掩盖重叠。
                r = (b[0] - a[0], b[1] - a[1])
                if (abs(_cross(r, (c[0] - a[0], c[1] - a[1]))) <= 1e-12
                        and _collinear_overlap(a, b, c, d)):
                    generated_issues.append(_issue(
                        f"overlap-{aid}-{bid}", "topology",
                        [f"member:{aid}", f"member:{bid}"], "共线杆件重叠"))
                    continue
                if not shared_endpoints or a == b or c == d:
                    continue
                shared = min(shared_endpoints)
                hit = (0.0 if ai == shared else 1.0,
                       0.0 if bi == shared else 1.0, nodes[shared])
            sa, sb, point = hit
            la = math.hypot((b[0] - a[0]) * (width - 1),
                            (b[1] - a[1]) * (height - 1))
            lb = math.hypot((d[0] - c[0]) * (width - 1),
                            (d[1] - c[1]) * (height - 1))
            sa, sb = (_snap_parameter(sa, la, tolerance),
                      _snap_parameter(sb, lb, tolerance))
            previous = old.get(tuple(pair), {})
            if shared_endpoints:
                decision, node_id = "connect", min(shared_endpoints)
                # 已有节点编号明确端点；短杆的像素吸附不能改变这一关系。
                sa = 0.0 if ai == node_id else 1.0
                sb = 0.0 if bi == node_id else 1.0
                point = nodes[node_id]
            else:
                decision = previous.get("decision", "unknown")
                node_id = previous.get("node_id") if decision == "connect" else None
            identifier = f"I-{aid}-{bid}"
            intersections.append({
                "id": identifier, "members": pair, "point": [float(point[0]), float(point[1])],
                "decision": decision, "node_id": node_id,
                "member_s": {str(aid): sa, str(bid): sb},
            })
            if decision == "unknown":
                generated_issues.append(_issue(
                    f"intersection-unknown-{aid}-{bid}", "intersection_unknown",
                    [f"intersection:{identifier}"], "交点连接关系尚未确认"))
    retained = [item for item in updated.get("issues") or []
                if not (str(item.get("id", "")).startswith(("duplicate-member-", "overlap-",
                                                             "intersection-unknown-")))]
    updated["intersections"] = intersections
    updated["issues"] = retained + generated_issues
    return updated


def resolve_intersection(draft: Mapping[str, Any], intersection_id: str,
                         decision: str) -> dict[str, Any]:
    """Resolve one intersection as connect or cross on a copied draft."""
    if decision not in {"connect", "cross"}:
        raise ValueError("交点决策必须是 connect 或 cross")
    updated = deepcopy(dict(draft))
    matches = [item for item in updated.get("intersections") or []
               if str(item.get("id")) == str(intersection_id)]
    if len(matches) != 1:
        raise ValueError("未知交点")
    item = matches[0]
    image_model = updated["image_model"]
    nodes, members = _geometry(image_model)
    endpoint_ids = []
    for member_id in item["members"]:
        member = members[int(member_id)]
        s = item["member_s"][str(member_id)]
        if s == 0.0:
            endpoint_ids.append(int(member["i"]))
        elif s == 1.0:
            endpoint_ids.append(int(member["j"]))
    if decision == "cross":
        if endpoint_ids:
            raise ValueError("构件端点形成的 T/端点连接不能标记为跨越")
        point = tuple(float(value) for value in item["point"])
        source = updated.get("source") or {}
        width, height = int(source.get("width_px", 0)), int(source.get("height_px", 0))
        tolerance = point_match_threshold(width, height)
        if any(math.hypot((point[0] - location[0]) * (width - 1),
                          (point[1] - location[1]) * (height - 1)) <= tolerance
               for location in nodes.values()):
            raise ValueError("交点处已有节点，必须连接或先删除该节点")
        item.update(decision="cross", node_id=None)
    else:
        if endpoint_ids:
            point = tuple(float(value) for value in item["point"])
            ranked = sorted((math.dist(point, nodes[node_id]), node_id)
                            for node_id in set(endpoint_ids))
            if len(ranked) > 1 and math.isclose(ranked[0][0], ranked[1][0], abs_tol=1e-12):
                raise ValueError("交点附近存在多个不同端点，需先合并或移动节点")
            node_id = ranked[0][1]
            # The tolerance decision becomes exact formal topology: move the reused
            # endpoint onto the mathematical intersection so the compiler sees it.
            for node in image_model["nodes"]:
                if int(node["id"]) == node_id:
                    node["u"], node["v"] = point
                    break
        else:
            node_id = max(nodes, default=0) + 1
            u, v = (float(value) for value in item["point"])
            image_model.setdefault("nodes", []).append({"id": node_id, "u": u, "v": v})
            updated.setdefault("entities", []).append({
                "kind": "node", "id": f"node-{node_id}", "confidence": None,
                "recognition_confidence": None, "verified": True,
                "image_geometry": {"point": [u, v]}, "source": "user",
                "target": {"node": node_id}, "payload": {},
            })
        item.update(decision="connect", node_id=node_id)
    for issue in updated.get("issues") or []:
        if issue.get("category") == "intersection_unknown" \
                and f"intersection:{intersection_id}" in issue.get("entity_refs", []):
            issue.update(status="resolved", resolution=decision, resolved_by="user")
    updated["revision"] = int(updated.get("revision", 0)) + 1
    updated["model"] = updated["merge_plan"] = updated["confirmation"] = None
    return updated


def delete_member(draft: Mapping[str, Any], member_id: int) -> dict[str, Any]:
    """Delete an unreferenced member, refusing dimensions, loads and intersections."""
    image_model = draft.get("image_model") or {}
    refs = []
    if any(item.get("target", {}).get("member") == member_id
           for item in draft.get("dimensions") or []):
        refs.append("dimension")
    members = {int(item["id"]): item for item in image_model.get("members") or []}
    for item in draft.get("intersections") or []:
        pair = [int(value) for value in item.get("members") or []]
        if member_id not in pair or len(pair) != 2:
            continue
        first, second = members.get(pair[0]), members.get(pair[1])
        shared = (set((int(first["i"]), int(first["j"])))
                  & set((int(second["i"]), int(second["j"])))) \
            if first and second else set()
        # 共享端点关系由几何自动重建，不是需要保护的人工交点决定。
        if not shared:
            refs.append("intersection")
    for block in [image_model, *(image_model.get("load_cases") or [])]:
        for collection in ("member_loads", "member_spans"):
            if any(item.get("member") == member_id for item in block.get(collection) or []):
                refs.append("load")
    if refs:
        raise ValueError(f"杆件 {member_id} 仍被引用: {', '.join(sorted(set(refs)))}")
    updated = deepcopy(dict(draft))
    before = len(updated["image_model"].get("members") or [])
    updated["image_model"]["members"] = [item for item in updated["image_model"]["members"]
                                                   if item.get("id") != member_id]
    if len(updated["image_model"]["members"]) == before:
        raise ValueError("未知杆件")
    updated["entities"] = [item for item in updated.get("entities") or []
                           if item.get("target", {}).get("member") != member_id]
    return detect_topology(updated)


def delete_node(draft: Mapping[str, Any], node_id: int) -> dict[str, Any]:
    image_model = draft.get("image_model") or {}
    refs = []
    if any(node_id in (item.get("i"), item.get("j")) for item in image_model.get("members") or []):
        refs.append("member")
    if any(item.get("node") == node_id for item in image_model.get("supports") or []):
        refs.append("support")
    for block in [image_model, *(image_model.get("load_cases") or [])]:
        for collection in ("nodal_loads", "settlements"):
            if any(item.get("node") == node_id for item in block.get(collection) or []):
                refs.append("load")
    if any(node_id in (item.get("target", {}).get("nodes") or [])
           for item in draft.get("dimensions") or []):
        refs.append("dimension")
    if refs:
        raise ValueError(f"节点 {node_id} 仍被引用: {', '.join(sorted(set(refs)))}")
    updated = deepcopy(dict(draft))
    before = len(updated["image_model"].get("nodes") or [])
    updated["image_model"]["nodes"] = [item for item in updated["image_model"]["nodes"]
                                                if item.get("id") != node_id]
    if len(updated["image_model"]["nodes"]) == before:
        raise ValueError("未知节点")
    updated["entities"] = [item for item in updated.get("entities") or []
                           if item.get("target", {}).get("node") != node_id]
    return detect_topology(updated)


def insert_member_node(draft: Mapping[str, Any], member_id: int, fraction: float) -> dict[str, Any]:
    """用户指定杆件内的作用位置，补节点并分段；已有荷载或尺寸引用不能自动迁移。"""
    if (not isinstance(fraction, (int, float)) or isinstance(fraction, bool)
            or not math.isfinite(fraction) or not 0 < fraction < 1):
        raise ValueError("作用位置必须在杆件两端之间，请填写大于 0 且小于 100 的百分比。")
    model = draft.get("image_model") or {}
    nodes, members = _geometry(model)
    original = members.get(member_id)
    if original is None:
        raise ValueError("所选杆件不存在，请重新选择。")
    if set(original) - {"id", "i", "j", "section", "material"}:
        raise ValueError("杆件含端部释放或其他属性，请先核对分段后的属性归属。")
    # 复用删除检查：拒绝已有荷载、尺寸或人工交点引用，避免偷偷重分配工程数据。
    try:
        updated = delete_member(draft, member_id)
    except ValueError as exc:
        raise ValueError("所选杆件仍被引用，请先核对并处理荷载、尺寸或交点引用后补充节点。") from exc
    new_node_id, new_member_id = max(nodes, default=0) + 1, max(members, default=0) + 1
    a, b = nodes[int(original["i"])], nodes[int(original["j"])]
    point = tuple(a[index] + fraction * (b[index] - a[index]) for index in range(2))
    source = draft.get("source") or {}
    width, height = int(source.get("width_px", 0)), int(source.get("height_px", 0))
    if width <= 1 or height <= 1:
        raise ValueError("草稿缺少有效图片尺寸，请重新加载图片后补充作用节点。")
    if any(math.hypot((point[0] - p[0]) * (width - 1), (point[1] - p[1]) * (height - 1))
           <= point_match_threshold(width, height) for p in nodes.values()):
        raise ValueError("作用位置过于接近已有节点，请使用已有节点或调整百分比。")
    updated["image_model"]["nodes"].append({"id": new_node_id, "u": point[0], "v": point[1]})
    first = {**deepcopy(original), "j": new_node_id}
    second = {**deepcopy(original), "id": new_member_id, "i": new_node_id}
    updated["image_model"]["members"].extend([first, second])
    entities = updated.setdefault("entities", [])
    def add(kind, ident, geometry):
        entity_id = f"user-{kind}-{ident}"
        while any(e.get("id") == entity_id for e in entities):
            entity_id += "-new"
        entities.append({"id": entity_id, "kind": kind, "target": {kind: ident},
            "source": "user", "verified": True, "confidence": None, "recognition_confidence": None,
            "image_geometry": geometry, "payload": {}})
    add("node", new_node_id, {"point": list(point)})
    add("member", member_id, {"line": [list(a), list(point)]})
    add("member", new_member_id, {"line": [list(point), list(b)]})
    for issue in updated.get("issues") or []:
        ref = f"member:{member_id}"
        if ref in (issue.get("entity_refs") or []):
            issue["entity_refs"] = sorted(set([*issue["entity_refs"], f"member:{new_member_id}"]))
            issue.update(status="open", resolution=None, resolved_by=None)
    updated["model"] = updated["merge_plan"] = updated["confirmation"] = None
    return detect_topology(updated)


def materialize_geometry(draft: Mapping[str, Any]) -> dict[str, Any]:
    """Materialize confirmed image geometry to SI Domain IR without engineering defaults."""
    work_plane, scale = draft.get("work_plane") or {}, draft.get("scale") or {}
    if work_plane.get("status") != "confirmed" or scale.get("status") != "confirmed":
        raise ValueError("工作平面和尺度必须先确认")
    image_model = draft.get("image_model") or {}
    source = draft.get("source") or {}
    nodes, _ = _geometry(image_model)
    anchor_id = int(scale["anchor_node"])
    if anchor_id not in nodes:
        raise ValueError("尺度锚点不存在")
    result_nodes = []
    for node_id, (u, v) in sorted(nodes.items()):
        xyz = image_to_model(
            u, v, width=int(source["width_px"]), height=int(source["height_px"]),
            anchor_uv=nodes[anchor_id], length_per_pixel=float(scale["length_per_pixel"]),
            plane=work_plane["plane"], offset=float(work_plane["offset"]),
            anchor_xyz=scale["anchor_coordinates_xyz"])
        result_nodes.append({"id": node_id, "x": xyz[0], "y": xyz[1], "z": xyz[2]})
    return {"schema_version": 1, "units": "N-m-Pa", "materials": [], "sections": [],
            "nodes": result_nodes, "members": deepcopy(image_model.get("members") or []),
            "supports": deepcopy(image_model.get("supports") or []),
            "nodal_loads": deepcopy(image_model.get("nodal_loads") or []),
            "member_loads": deepcopy(image_model.get("member_loads") or []),
            "member_spans": deepcopy(image_model.get("member_spans") or []),
            "settlements": deepcopy(image_model.get("settlements") or []),
            "load_cases": deepcopy(image_model.get("load_cases") or [])}
